import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class DynamicProgrammingTour {
    public static void main(String[] args) {
        // 0/1 knapsack: best value with capacity 10
        String[] items = {"tent", "stove", "camera", "book", "snacks"};
        int[] weight = {5, 4, 6, 3, 2};
        int[] value = {10, 40, 30, 50, 20};
        int capacity = 10, n = items.length;
        int[][] best = new int[n + 1][capacity + 1];         // best[i][c]: first i items, capacity c
        for (int i = 1; i <= n; i++) {
            for (int c = 0; c <= capacity; c++) {
                best[i][c] = best[i - 1][c];                  // skip item i-1
                if (weight[i - 1] <= c) {
                    best[i][c] = Math.max(best[i][c], best[i - 1][c - weight[i - 1]] + value[i - 1]);   // take it
                }
            }
        }
        List<String> packed = new ArrayList<>();
        for (int i = n, c = capacity; i > 0; i--) {           // walk back through the table
            if (best[i][c] != best[i - 1][c]) {
                packed.add(items[i - 1]);
                c -= weight[i - 1];
            }
        }
        Collections.reverse(packed);
        System.out.println("knapsack (capacity 10): value " + best[n][capacity] + " with " + packed);

        // Climbing stairs taking 1 or 2 steps: ways[i] = ways[i-1] + ways[i-2]
        long[] ways = new long[51];
        ways[0] = 1;
        ways[1] = 1;
        for (int i = 2; i <= 50; i++) ways[i] = ways[i - 1] + ways[i - 2];
        System.out.println("ways to climb 10 stairs: " + ways[10] + ", 50 stairs: " + ways[50]);
    }
}

import java.util.Arrays;

public class KnapsackMemo {
    static int[] weight, value;
    static int[][] memo;
    static long calls;

    static int naive(int i, int c) {
        calls++;
        if (i == weight.length) return 0;
        int best = naive(i + 1, c);                                         // skip item i
        if (weight[i] <= c) best = Math.max(best, value[i] + naive(i + 1, c - weight[i]));   // take it
        return best;
    }

    static int memoized(int i, int c) {
        calls++;
        if (i == weight.length) return 0;
        if (memo[i][c] != -1) return memo[i][c];                            // state already solved
        int best = memoized(i + 1, c);
        if (weight[i] <= c) best = Math.max(best, value[i] + memoized(i + 1, c - weight[i]));
        return memo[i][c] = best;
    }

    public static void main(String[] args) {
        int n = 20, capacity = 50;
        weight = new int[n];
        value = new int[n];
        for (int i = 0; i < n; i++) {                                       // deterministic sample items
            weight[i] = 1 + (i * 7) % 10;
            value[i] = 10 + (i * 13) % 37;
        }
        System.out.println("weights " + Arrays.toString(weight));
        System.out.println("values  " + Arrays.toString(value));

        calls = 0;
        int a = naive(0, capacity);
        long naiveCalls = calls;
        memo = new int[n][capacity + 1];
        for (int[] row : memo) Arrays.fill(row, -1);
        calls = 0;
        int b = memoized(0, capacity);
        int solved = 0;
        for (int[] row : memo) for (int v : row) if (v != -1) solved++;
        System.out.println("best value " + a + " (naive) = " + b + " (memoized)");
        System.out.println("naive calls: " + naiveCalls + ", memoized calls: " + calls
                + ", states solved: " + solved + " of " + n * (capacity + 1));
    }
}

public class KnapsackTabulation {
    public static void main(String[] args) {
        int[] w = {1, 3, 4, 5};
        int[] v = {2, 4, 5, 7};
        int capacity = 7, n = w.length;

        int[][] dp = new int[n + 1][capacity + 1];            // row 0: no items, all zeros
        for (int i = 1; i <= n; i++) {
            for (int c = 0; c <= capacity; c++) {
                dp[i][c] = dp[i - 1][c];                       // skip
                if (w[i - 1] <= c) dp[i][c] = Math.max(dp[i][c], dp[i - 1][c - w[i - 1]] + v[i - 1]);   // take
            }
        }
        System.out.println("items (w,v): (1,2) (3,4) (4,5) (5,7), capacity " + capacity);
        StringBuilder header = new StringBuilder("        c:");
        for (int c = 0; c <= capacity; c++) header.append(String.format("%3d", c));
        System.out.println(header);
        for (int i = 0; i <= n; i++) {
            StringBuilder row = new StringBuilder(String.format("%-10s", i == 0 ? "no items" : "item " + i));
            for (int c = 0; c <= capacity; c++) row.append(String.format("%3d", dp[i][c]));
            System.out.println(row);
        }
        System.out.println("best = " + dp[n][capacity]);

        int[] down = new int[capacity + 1], up = new int[capacity + 1];
        for (int i = 0; i < n; i++) {
            for (int c = capacity; c >= w[i]; c--) down[c] = Math.max(down[c], down[c - w[i]] + v[i]);   // correct
            for (int c = w[i]; c <= capacity; c++) up[c] = Math.max(up[c], up[c - w[i]] + v[i]);         // reuses items
        }
        System.out.println("one row, capacity loop downward: " + down[capacity]);
        System.out.println("one row, capacity loop upward:   " + up[capacity] + " (takes item (1,2) seven times)");
    }
}

