import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;

public class LongestIncreasingSubsequence {
    public static void main(String[] args) {
        int[] a = {10, 9, 2, 5, 3, 7, 101, 18, 4, 19};
        int n = a.length;
        int[] dp = new int[n], parent = new int[n];
        for (int i = 0; i < n; i++) {
            dp[i] = 1;                                  // the element alone
            parent[i] = -1;
            for (int j = 0; j < i; j++) {
                if (a[j] < a[i] && dp[j] + 1 > dp[i]) {  // extend the best run ending at j
                    dp[i] = dp[j] + 1;
                    parent[i] = j;
                }
            }
        }
        System.out.println("a      = " + Arrays.toString(a));
        System.out.println("dp     = " + Arrays.toString(dp));
        System.out.println("parent = " + Arrays.toString(parent));

        int end = 0;
        for (int i = 1; i < n; i++) if (dp[i] > dp[end]) end = i;
        List<Integer> lis = new ArrayList<>();
        for (int i = end; i != -1; i = parent[i]) lis.add(a[i]);
        Collections.reverse(lis);
        System.out.println("longest increasing subsequence: " + lis + " (length " + dp[end] + ")");
    }
}

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class OverlappingSubproblems {
    static int[] coins = {1, 4, 5};
    static int[] timesSolved;

    static int naive(int amount) {
        timesSolved[amount]++;
        if (amount == 0) return 0;
        int best = Integer.MAX_VALUE;
        for (int c : coins) if (c <= amount) best = Math.min(best, 1 + naive(amount - c));
        return best;
    }

    public static void main(String[] args) {
        int target = 13;
        timesSolved = new int[target + 1];
        int answer = naive(target);
        System.out.println("naive recursion: " + answer + " coins");
        StringBuilder counts = new StringBuilder();
        for (int a = 0; a <= target; a++) counts.append(a).append(":").append(timesSolved[a]).append(' ');
        System.out.println("times each amount was solved: " + counts.toString().trim());
        System.out.println("total calls: " + Arrays.stream(timesSolved).sum() + ", distinct amounts: " + (target + 1));

        int[] best = new int[target + 1], used = new int[target + 1];
        Arrays.fill(best, Integer.MAX_VALUE);           // "not reachable yet", not 0
        best[0] = 0;
        for (int a = 1; a <= target; a++) {             // each amount solved exactly once
            for (int c : coins) {
                if (c <= a && best[a - c] != Integer.MAX_VALUE && best[a - c] + 1 < best[a]) {
                    best[a] = best[a - c] + 1;
                    used[a] = c;
                }
            }
        }
        List<Integer> picked = new ArrayList<>();
        for (int a = target; a > 0; a -= used[a]) picked.add(used[a]);
        System.out.println("table: best = " + Arrays.toString(best));
        System.out.println("coins for " + target + ": " + picked + " (greedy would use 5, 5, 1, 1, 1)");
    }
}

